const copy={fa:{eyebrow:'آرشیو دلار آمریکا · بازار آزاد',title:'قیمت سالانه دلار در ایران',subtitle:'کمترین و بیشترین قیمت ثبت‌شده برای یک دلار، به تومان.',sortLabel:'مرتب‌سازی:',year:'سال',minimum:'کمترین قیمت',maximum:'بیشترین قیمت',yearHeading:'سال شمسی',minHeading:'کمترین · تومان',maxHeading:'بیشترین · تومان',note:'۱۳۶۴ تا ۱۳۷۹: کمترین و بیشترین میانگین ماهانه، نه نوسان روزانه. از ۱۳۸۰: داده‌های روزانه. — یعنی فقط دادهٔ سالانه موجود است. سال جاری تا آخرین دادهٔ موجود محاسبه شده است.',sourceLabel:'منبع داده:',asc:'صعودی ↑',desc:'نزولی ↓',light:'تم روشن',dark:'تم تاریک',loading:'در حال دریافت داده‌ها…',error:'دریافت داده‌ها ناموفق بود. لطفاً صفحه را دوباره بارگذاری کنید.',coverage:'آخرین داده:',updated:'دریافت آرشیو:'},en:{eyebrow:'US DOLLAR ARCHIVE · OPEN MARKET',title:'Yearly dollar prices in Iran',subtitle:'Lowest and highest recorded prices for one US dollar, in toman.',sortLabel:'Sort by:',year:'Year',minimum:'Minimum price',maximum:'Maximum price',yearHeading:'Persian year',minHeading:'Minimum · toman',maxHeading:'Maximum · toman',note:'1364–1379: ranges of monthly averages, not daily extremes. From 1380: daily records. — means only an annual observation is available. The current year covers available data to date.',sourceLabel:'Data source:',asc:'Ascending ↑',desc:'Descending ↓',light:'Light theme',dark:'Dark theme',loading:'Loading data…',error:'Could not load data. Please reload the page.',coverage:'Latest observation:',updated:'Archive retrieved:'}};
const $=id=>document.getElementById(id);
const read=key=>{try{return localStorage.getItem(key)}catch{return null}};
const save=(key,value)=>{try{localStorage.setItem(key,value)}catch{}};
let lang=read('language')==='en'?'en':'fa',theme=read('theme')||'light',ascending=false,data=null,failed=false;
function render(){const t=copy[lang];document.documentElement.lang=lang;document.documentElement.dir=lang==='fa'?'rtl':'ltr';document.documentElement.dataset.theme=theme;document.title=t.title;for(const id of ['title','sortLabel','yearHeading','sourceLabel'])$(id).textContent=t[id];for(const [id,key] of [['minHeading','minimum'],['maxHeading','maximum']]){const unit=document.createElement('small');unit.textContent=lang==='fa'?' (تومان)':' (toman)';$(id).replaceChildren(document.createTextNode(lang==='fa'?(key==='minimum'?'کمترین':'بیشترین'):(key==='minimum'?'Minimum':'Maximum')),unit);}$('language').textContent=lang==='fa'?'EN':'FA';$('language').setAttribute('aria-label',lang==='fa'?'English':'فارسی');$('language').title=lang==='fa'?'English':'فارسی';$('theme').textContent=theme==='dark'?'☀':'☾';$('theme').setAttribute('aria-label',t[theme==='dark'?'light':'dark']);$('theme').title=t[theme==='dark'?'light':'dark'];$('theme').setAttribute('aria-pressed',String(theme==='dark'));$('direction').textContent=ascending?'↑':'↓';$('direction').setAttribute('aria-label',t[ascending?'asc':'desc']);$('direction').title=t[ascending?'asc':'desc'];for(const option of $('sort').options)option.textContent=t[option.value];$('status').textContent=failed?t.error:data?'':t.loading;if(!data)return;const locale=lang==='fa'?'fa-IR':'en-US',nf=new Intl.NumberFormat(locale,{maximumFractionDigits:0});const date=value=>new Intl.DateTimeFormat(locale+'-u-ca-persian',{year:'numeric',month:'long',day:'numeric',timeZone:'UTC'}).format(new Date(value+'T12:00:00Z'));$('coverage').textContent=t.coverage+' '+date(data.latestDate);const key=$('sort').value;const sorted=[...data.years].sort((a,b)=>{if(a[key]===null&&b[key]!==null)return 1;if(b[key]===null&&a[key]!==null)return -1;return (ascending?1:-1)*((a[key]??0)-(b[key]??0))||b.year-a.year});$('rows').replaceChildren(...sorted.map(row=>{const tr=document.createElement('tr');for(const [index,value] of [row.year,row.minimum,row.maximum].entries()){const td=document.createElement('td');td.textContent=value===null?'—':index===0?new Intl.NumberFormat(locale,{useGrouping:false}).format(value):nf.format(value);tr.append(td)}return tr}));}
$('language').onclick=()=>{lang=lang==='fa'?'en':'fa';save('language',lang);render()};$('theme').onclick=()=>{theme=theme==='light'?'dark':'light';save('theme',theme);render()};$('sort').onchange=render;$('direction').onclick=()=>{ascending=!ascending;render()};render();fetch('data.json').then(r=>{if(!r.ok)throw Error(r.status);return r.json()}).then(value=>{data=value;render()}).catch(()=>{failed=true;render()});
